import statistics


def resume_salaires(salaires):
    moyenne = round(statistics.mean(salaires))
    mediane = statistics.median(salaires)
    ecart = moyenne - mediane
    return {"moyenne": moyenne, "mediane": mediane, "ecart": ecart, "alerte": ecart > 0.2 * mediane}
